window.kbPageData["views/entry/k-7d452819897a6ed2"] = {"key":"entry/k-7d452819897a6ed2","state":{"route":"entry/k-7d452819897a6ed2"},"node":{"id":"k-7d452819897a6ed2","mode":"k","title":"刑法属地管辖的行为地与结果地","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["我国刑法属地管辖的行为地和结果地规则"],"qs":["国考 2024 行政执法 行测#12"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"犯罪行为或犯罪结果有一项发生在中华人民共和国领域内，即视为在我国领域内犯罪。除法律有特别规定外，在我国领域内犯罪适用我国刑法。","review":{"definition":"犯罪行为或犯罪结果有一项发生在中华人民共和国领域内，即视为在我国领域内犯罪。除法律有特别规定外，在我国领域内犯罪适用我国刑法。","explanation":"A项的行为发生在我国境内机场，受害人出境后死亡，境内行为已满足属地管辖的条件。C项的电话教唆行为发生在我国境内，境外实施的杀人行为也不影响我国对境内教唆行为适用刑法。题目问我国刑法不具有管辖权的情形，A、C均应排除。","references":[],"evidence":"犯罪的行为或者结果有一项发生在中华人民共和国领域内的","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 行测#12":{"paper":"国考 2024 行政执法 行测","n":12,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",3],"asrc":["6493f3a6a55c38431852.pdf",4],"card":"09c18159a03e15fe052d6091","links":[{"id":"k-7d452819897a6ed2","role":"直接考查","why":"行为或结果有一项发生在我国领域内即可认定为领域内犯罪，据此判断境内投毒和境内教唆的情形。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-7d452819897a6ed2":[["国考 2024 行政执法 行测#12"]]}};
